static void iter_load_optimize_prefix(struct iter_load_context *ctx)
{
	const char *pos, *last_sep = NULL;

	if (!ctx->iter->glob)
		return;

	for (pos = ctx->iter->glob; *pos; pos++) {
		switch (*pos) {
		case '?':
		case '*':
		case '[':
		case '\\':
			break;
		case '/':
			last_sep = pos;
			/* FALLTHROUGH */
		default:
			continue;
		}
		break;
	}

	if (last_sep) {
		ctx->ref_prefix = ctx->iter->glob;
		ctx->ref_prefix_len = (last_sep - ctx->ref_prefix) + 1;
	}
}

